const QIC={ghoul:'skull',brute:'skull',spitter:'skull',elite:'skull',rat:'skull',bomb:'skull',shield:'res',boss:'power',props:'crate',spati:'crate',chest:'stash',fire:'el',acid:'leech',shock:'rate',zone:'radio',trade:'coins',rescue:'person',shrine:'segen',wave:'flag'};// quest type -> placeholder icon (painted icons: docs/chatgpt-assets.md batch U02)
const ui=(k,s)=>`<svg class="uic" width="${s||18}" height="${s||18}" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2" stroke-linecap="round" stroke-linejoin="round" aria-hidden="true">${UIP[k]||''}</svg>`;
// stat rows: icon and a one-sentence tooltip (hover on desktop, tap on touch), keyed by the SROWS name
const SINFO={'Kampfkraft':['power','Gesamtwert aus Schaden, Angriffstempo, Leben und Widerstand. Höher heißt stärker.'],'Schaden pro Treffer':['dmg','Grundschaden jedes Treffers, bevor Krit und Elemente dazukommen.'],'Angriffe pro Sekunde':['rate','Wie oft du pro Sekunde zuschlägst.'],'Krit-Chance':['crit','Chance, dass ein Treffer doppelten Schaden macht.'],'Leben':['hp','Wie viel Schaden du aushältst, bevor du fällst.'],'Widerstand':['res','Dieser Anteil jedes erlittenen Treffers wird abgezogen.'],'Lauftempo':['spd','Deine Laufgeschwindigkeit, 100 % ist normal.'],'Leben pro Sekunde':['regen','So viel Leben heilst du jede Sekunde von selbst.'],'Elementarschaden':['el','Bonus für Feuer-, Säure- und Stromschaden deiner Waffe.'],'Leben pro Kill':['leech','So viel Leben bekommst du für jeden besiegten Gegner.'],'Beuteglück':['luck','Erhöht die Chance auf seltenere Beute.'],'Sprint-Abklingzeit':['dash','So lange dauert es, bis du wieder sprinten kannst.'],'Elemente':['el','Elemente deiner Ausrüstung. Gegner sind gegen manche schwach, gegen manche immun.']};
const sName=n=>{const q=SINFO[n];return q?`<span class="sn" data-tip="${q[1]}" tabindex="0">${ui(q[0],15)}${n}<i class="tq">?</i></span>`:`<span>${n}</span>`;};
let sgSel=null,invTab='bag',invFrom='menu',sel=null,invMsg='',allArm=false;
function cloudLine(){const m={off:'Spielstand auf diesem Gerät',sync:'Cloud wird geladen',on:'Cloud-Speicher aktiv · auf allen Geräten',slow:'Cloud gerade nicht erreichbar · speichert lokal',err:'Cloud nicht verfügbar · speichert lokal'};
  if(cloud.state==='off'&&os.code){const o={sync:'Online-Spielstand wird abgeglichen',on:'Online gespeichert · Code '+osFmt(os.code),slow:'Online gerade nicht erreichbar · speichert lokal'};return`<div class="cloud${os.state==='on'?' on':''}">${o[os.state]||o.sync}</div>`;}
  return`<div class="cloud${cloud.state==='on'?' on':''}">${m[cloud.state]}</div>`;}
// district flavour (x,y: old map positions, unused since the v0.50 network map in js/ubahn.js)
