let menuOpt=false,menuEnd=false;const mp=m=>Math.round(m.p*(hasS('schmied')?.7:1));
function distCard(i){const d=DIST[i],m=DMAP[i]||{},b=S.best[i],st=b>=WAVES?'<span class="ok">Befreit</span>':b?`Rekord: Welle ${b}/${WAVES}`:'Unerforscht';const w=Object.entries(RES[BK[d.b]]||{}).filter(q=>q[1]>1.2).map(q=>`<span style="color:${ELC[q[0]]}">${ELN[q[0]]}</span>`).join(', ');
  return`<div class="dcard"><div class="dtop"><span class="dn">${d.n}</span><span class="dm">${st}</span></div><div class="sub">${m.d||''}</div>
  <div class="dgrid"><span>Gegnerstufe</span><b>${d.lvl+1+S.threat*3}+</b><span>Endgegner</span><b>${BN[d.b]||'?'}</b><span>Schwäche</span><b>${w||'keine'}</b></div>${d.wet?'<div class="sub" style="color:#43d1cf">Regen: Strom springt weiter, Feuer brennt kürzer. Implantate fallen hier.</div>':''}</div>`;}
// v0.82 weapon power (Kraft) picked before the run, and a short reminder line (not blocking) when no meal is cooked or the bag holds better gear
function krPick(){const w=S.eq.w,cur=krOf(w);return`<div class="krsel"><div class="lbl">${KIND[w.kind].n} · Kraft wählen</div><div class="krrow">${KR[w.kind].map((p,i)=>`<button class="krb${p===cur?' sel':''}${p.u?' ult':''}" data-kr="${i}" aria-pressed="${p===cur}">${krIcon(p.k,44)}<span class="krn">${krName(p,w)}</span><span class="krc">${p.u?'Ultimativ · ':''}${p.cd} s</span></button>`).join('')}</div><p class="hint krd">${cur.d}</p></div>`;}
function goWarn(){const o=[];if(!S.meal&&MEALS.some(m=>(!m.req||S.camp[m.req])&&Object.entries(m.c).every(([z,v])=>(S.mat[z]||0)>=v)))o.push('nichts gekocht');if(S.bag.some(it=>it.slot==='w'&&better(it)))o.push('stärkere Waffe im Rucksack');else if(S.bag.some(it=>better(it)))o.push('bessere Ausrüstung im Rucksack');return o.length?`<p class="hint gowarn">Achtung: ${o.join(' · ')}</p>`:'';}
function renderMenu(){refresh();if(os.pend&&!os.busy&&state==='menu')osPull();// online save: conflict seen during a run, adopt now
  if(menuTun!=null&&!lineOpen(menuTun))menuTun=null;// selected tunnel gone (new game, imported save)
  
  const jd=S.jobs.filter(j=>j.p>=j.t).length,lock=menuTun!=null?!lineOpen(menuTun):S.dist>=S.unlocked;
  const opt='';// v0.58: options live in their own window (renderOpts)
  $('menubox').innerHTML=`<div class="mhead"><h1>Ruinenstadt</h1><div class="mres"><span>Schrott <b>${S.scrap}</b></span><span>Kampfkraft <b>${power(ST)}</b></span><button class="btn sm" data-m="opt">Optionen</button></div></div>${opt}
  <div class="mgrid"><div class="mleft"><canvas id="campc" width="800" height="300" aria-label="Dein Lager"></canvas>${netSVG()}</div>
  <div class="mright">${menuTun!=null?tunCard(menuTun):distCard(S.dist)}
  ${S.tmax>0?`<div class="row thr"><button class="btn sm" data-m="thm" aria-label="Bedrohung senken">−</button><div class="scrap">Bedrohung <b>${S.threat}</b> von ${S.tmax}<br><span style="font-size:14px">${S.threat?`Gegner +${S.threat*25}% Leben · Beute +${S.threat*3} Stufen`:'Grundbedrohung'}</span></div><button class="btn sm" data-m="thp" aria-label="Bedrohung erhöhen">+</button></div>`:'<p class="hint">Befreie einen Bezirk, um höhere Bedrohung mit besserer Beute freizuschalten.</p>'}
  ${menuTun==null&&S.best[S.dist]>=WAVES?`<div class="two"><button class="btn sm${menuEnd?'':' main'}" data-m="end"${menuEnd?'':' aria-pressed="true"'}>${WAVES} Wellen</button><button class="btn sm${menuEnd?' main':''}" data-m="end"${menuEnd?' aria-pressed="true"':''}>Endlos · Rekord ${S.eb[S.dist]||0}</button></div>`:''}
  ${krPick()}${goWarn()}
  ${S.meal?`<p class="hint" style="color:var(--good)">Gekocht: ${MEALS.find(m=>m.k===S.meal).n} · ${MEALS.find(m=>m.k===S.meal).d}</p>`:''}
  <button class="btn main go" id="go"${lock?' disabled':''}>${menuTun!=null?'In den Tunnel':menuEnd&&S.best[S.dist]>=WAVES?'Endlos losziehen':'Losziehen'}</button>
  <button class="btn" data-m="base">Basis betreten · zu Fuß</button>
  <div class="nav3"><button class="btn" data-m="inv">Inventar${S.bag.some(it=>better(it))?' <span class="ok">▲</span>':''}</button><button class="btn" data-m="shop">Handwerk</button><button class="btn" data-m="jobs">Quests${jd?` <span class="ok">${jd}</span>`:''}</button></div>
  ${S.unlocked>=2?(()=>{const pl=dailyPlan(),db=S.daily&&S.daily.k===dayKey()?S.daily:null;return`<div class="dcard daily"><div class="dtop"><span class="dn" style="font-size:26px">Tageskampf</span><span class="dm">${db?'Bestwert '+db.best:'Heute noch offen'}</span></div><div class="sub">${DIST[pl.d].n} · ${pl.mods.map(k=>`<b style="color:var(--ember)">${DMODS[k][0]}</b>: ${DMODS[k][1]}`).join(' · ')}</div><div class="sub">Gleiche Karte und Gegner für alle Versuche heute. Punkte: Kills, Wellen, Sieg.</div><button class="btn sm main" data-m="daily">Tageskampf starten</button></div>`;})():''}
  <p class="hint">${S.rec.kills.toLocaleString('de-DE')} Gegner · ${S.rec.legs} Legendäre · ${S.rec.runs} Expeditionen · ${S.rec.wins} Befreiungen · ${Math.round(S.rec.time/60)} Min.</p></div></div>`;
  drawCamp();
}
function drawCamp(){const c=$('campc');if(!c)return;const g=c.getContext('2d'),W=800,H=300,K=S.camp;g.save();
  const sky=g.createLinearGradient(0,0,0,H);sky.addColorStop(0,'#120e0c');sky.addColorStop(1,'#2a211b');g.fillStyle=sky;g.fillRect(0,0,W,H);
  g.fillStyle='#0c0907';for(let i=0;i<14;i++){const x=i*60,h=40+((i*37)%70);g.fillRect(x,95-h,48,h+20);if(i%3===0){g.fillStyle='#e0892e';g.fillRect(x+12,95-h+14,6,8);g.fillStyle='#0c0907';}}
  g.fillStyle='#231b16';g.fillRect(0,110,W,H-110);for(let i=0;i<300;i++){g.fillStyle=Math.random()<.5?'rgba(0,0,0,.2)':'rgba(255,230,200,.04)';g.fillRect(Math.random()*W,110+Math.random()*(H-110),3,2);}
  const fx=400,fy=215,gl=g.createRadialGradient(fx,fy,0,fx,fy,220);gl.addColorStop(0,'rgba(255,140,50,.38)');gl.addColorStop(1,'rgba(255,140,50,0)');g.fillStyle=gl;g.fillRect(0,0,W,H);
  const tent=(x,y,col,mark)=>{g.fillStyle='rgba(0,0,0,.35)';g.fillRect(x-56,y+2,116,10);g.fillStyle=col;g.beginPath();g.moveTo(x-55,y);g.lineTo(x,y-70);g.lineTo(x+55,y);g.fill();g.fillStyle='rgba(0,0,0,.35)';g.beginPath();g.moveTo(x,y-70);g.lineTo(x+55,y);g.lineTo(x+10,y);g.fill();g.fillStyle='#0b0806';g.beginPath();g.moveTo(x-12,y);g.lineTo(x,y-34);g.lineTo(x+12,y);g.fill();if(mark){g.fillStyle=mark;g.fillRect(x-4,y-56,8,20);g.fillRect(x-10,y-50,20,8);}};
  tent(250,225,'#5a4a30');
  if(K.sani)tent(560,230,'#d6cfc0','#3B6D11');
  if(K.turm){g.fillStyle='#4a3424';g.fillRect(690,60,8,170);g.fillRect(740,60,8,170);g.strokeStyle='#4a3424';g.lineWidth=4;g.beginPath();g.moveTo(694,220);g.lineTo(744,120);g.moveTo(744,220);g.lineTo(694,120);g.stroke();g.fillStyle='#5a4030';g.fillRect(680,40,78,28);g.fillStyle='#3a2a20';g.beginPath();g.moveTo(674,42);g.lineTo(719,14);g.lineTo(764,42);g.fill();}
  if(K.funk){g.strokeStyle='#3a342e';g.lineWidth=3;g.beginPath();g.moveTo(620,225);g.lineTo(628,40);g.lineTo(636,225);g.moveTo(612,225);g.lineTo(628,120);g.lineTo(644,225);g.stroke();g.fillStyle='#ff4030';g.beginPath();g.arc(628,38,5,0,7);g.fill();}
  if(K.halle){g.fillStyle='rgba(0,0,0,.35)';g.fillRect(64,238,170,10);g.fillStyle='#4a4740';g.fillRect(60,170,170,70);g.fillStyle='#3f3d38';g.beginPath();g.moveTo(52,172);g.lineTo(145,140);g.lineTo(238,172);g.fill();g.fillStyle='#14100d';g.fillRect(120,195,50,45);g.fillStyle='rgba(0,0,0,.25)';for(let i=0;i<6;i++)g.fillRect(122,200+i*7,46,2);}
  if(K.garten){for(let r=0;r<3;r++){g.fillStyle='#3a2a1e';g.fillRect(300+r*60,262,48,22);for(let k=0;k<4;k++){g.fillStyle=['#4a5a2a','#3b4a22','#5a6a30'][k%3];g.beginPath();g.arc(306+r*60+k*12,262,6,0,7);g.fill();}}}
  if(K.presse){g.fillStyle='#5a5650';g.fillRect(470,150,70,70);g.fillStyle='#7a766c';g.fillRect(470,150,70,10);g.fillStyle='#3a3630';g.fillRect(480,170,50,40);g.fillStyle='#c23a2e';g.fillRect(528,160,8,8);}
  g.fillStyle='#4a4038';for(let i=0;i<8;i++){const a=i/8*6.283;g.beginPath();g.arc(fx+Math.cos(a)*30,fy+12+Math.sin(a)*10,8,0,7);g.fill();}
  g.fillStyle='#2a1d14';g.fillRect(fx-22,fy+2,44,8);
  for(let k=0;k<6;k++){g.fillStyle=k%2?'#EF9F27':'#FAC775';const h=30+((k*13)%22);g.beginPath();g.moveTo(fx-20+k*7,fy+4);g.lineTo(fx-12+k*7,fy+4);g.lineTo(fx-16+k*7,fy+4-h);g.fill();}
  const fig=(x,y,j,hat)=>{g.fillStyle='rgba(0,0,0,.4)';g.beginPath();g.ellipse(x,y+2,14,4,0,0,7);g.fill();g.fillStyle='#1e1610';g.fillRect(x-6,y-18,5,18);g.fillRect(x+1,y-18,5,18);g.fillStyle=j;g.fillRect(x-9,y-42,18,26);g.fillStyle='#d9b48f';g.beginPath();g.arc(x,y-50,8,0,7);g.fill();if(hat){g.fillStyle=hat;g.beginPath();g.arc(x,y-53,8.5,Math.PI,0);g.fill();g.fillRect(x-10,y-54,20,3);}};
  SURV.forEach((v,i)=>{if(hasS(v.k))fig(150+i*95+(i>2?190:0),282-(i%2)*14,v.c,null);});
  fig(470,250,'#26304a','#f2c230');fig(330,245,LOOK[S.eq.a?baseOf(S.eq.a):'none'].j,null);
  g.font='600 22px sans-serif';g.fillStyle='rgba(234,217,192,.65)';g.textAlign='left';g.fillText('Ilse',446,282);g.textAlign='right';g.fillText(CAMP.filter(c=>K[c.k]).length+'/'+CAMP.length+' gebaut',788,288);
  g.restore();}
$('menubox').addEventListener('click',e=>{const ln=e.target.closest('.line');if(ln){const k=+ln.dataset.l;if(lineOpen(k)){initAudio();sfx('ui');menuTun=k;renderMenu();}return;}const nd=e.target.closest('.node');if(nd){initAudio();const i=+nd.dataset.d;if(i<S.unlocked){sfx('ui');menuTun=null;S.dist=i;save();buildWorld(DIST[i]);renderMenu();}return;}const t=e.target.closest('button');if(!t)return;initAudio();sfx('ui');
  if(t.dataset.d!==undefined){const i=+t.dataset.d;if(i<S.unlocked){menuTun=null;S.dist=i;save();buildWorld(DIST[i]);renderMenu();}return;}
  if(t.dataset.kr!=null){const k=S.eq.w.kind;S.kr=S.kr||{};S.kr[k]=+t.dataset.kr;save();refresh();renderMenu();return;}
  if(t.id==='go')return menuTun!=null?startTunnel(menuTun):startRun(S.dist,menuEnd&&S.best[S.dist]>=WAVES);if(t.dataset.m==='daily')return startRun(0,false,true);if(t.dataset.m==='end'){menuEnd=!menuEnd;renderMenu();return;}const m=t.dataset.m;if(m==='base')return enterBase();if(m==='inv'||m==='shop'||m==='jobs'){invTab=m==='inv'?'bag':m;openInv('menu');}
  if(m==='mute'){setMute(!S.mute);renderMenu();}if(m==='eco'){setEco(!S.eco);renderMenu();}if(m==='thm'){S.threat=Math.max(0,S.threat-1);save();renderMenu();}if(m==='thp'){S.threat=Math.min(S.tmax,S.threat+1);save();renderMenu();}if(m==='music'){S.music=!S.music;save();if(S.music)startMusic();else stopMusic();renderMenu();}if(m==='opt')openOpts('menu');if(m==='auto'){S.auto=!autoAtk();save();renderMenu();}if(m==='hap'){S.hap=((S.hap==null?1:S.hap)+1)%3;save();buzz(12);renderMenu();}if(m==='fs'){S.fs=S.fs===0?1:0;save();if(S.fs===0&&document.fullscreenElement)document.exitFullscreen().catch(()=>{});renderMenu();}if(m==='exp')exportSave();if(m==='imp')importSave();if(m==='new')newGame();if(m==='diff'){S.diff=((S.diff==null?1:S.diff)+1)%3;save();renderMenu();}});
